#include "../../work/vcmi-wasm/lib/era/EraPhysicalDeflection.h"
#include <cassert>
int main(){using D=era_bridge::PhysicalDeflection;for(int rank=0;rank<=10;rank++){auto valid=D::decode(49,rank*5),odd=D::decode(200,rank*5);assert(valid.strength==50);assert(odd.strength==-55);int wins=0;for(int r=1;r<=100;r++){wins+=valid.succeeds(r);for(int damage=0;damage<1000;damage++){assert(valid.apply(damage,valid.succeeds(r))==(r<=rank*5?damage/2:damage));assert(odd.apply(damage,odd.succeeds(r))==damage);}}assert(wins==rank*5);assert(valid.needsRoll()==(rank>0));}auto alt=D::decode(125,60);assert(alt.strength==60&&alt.chance==25);assert(alt.apply(101,true)==40);int notices=0;auto notify=[&](int strength,int chance){assert(strength==50&&chance==50);++notices;};auto block=D::decode(49,50);assert(block.apply(101,false,notify)==101&&notices==0);assert(block.apply(101,true,notify)==50&&notices==1);assert(block.apply(-101,true,notify)==-50&&notices==2);assert(D::decode(200,100).apply(101,true,notify)==101&&notices==2);assert(block.apply(101,true)==50&&notices==2);}
